#pragma once
#include "LegacyOpenAIResponsesAgent.hpp"
#include "slic3r/GUI/JusPrin/Agent/OpenAIResponsesAgent.hpp"
#include <fstream>
#include <stdexcept>
namespace Slic3r::GUI::JusPrin::Agent {
class ComparingResponsesAgent final : public IAgentService {
    struct Pending { LegacyAgentHttpRequest request; LegacyIAgentHttpTransport::EventFn callback; };
    struct State { std::deque<Pending> pending; };
    struct BaselineTransport final : LegacyIAgentHttpTransport {
        std::shared_ptr<State> state;
        explicit BaselineTransport(std::shared_ptr<State> s) : state(std::move(s)) {}
        bool post(LegacyAgentHttpRequest request, EventFn callback) override {
            state->pending.push_back({std::move(request), std::move(callback)});
            return true;
        }
        void cancel() override {}
    };
    struct ComparingTransport final : IAgentHttpTransport {
        std::shared_ptr<State> state;
        std::unique_ptr<IAgentHttpTransport> transport;
        ComparingTransport(std::shared_ptr<State> s, std::unique_ptr<IAgentHttpTransport> t)
            : state(std::move(s)), transport(std::move(t)) {}
        bool post(AgentHttpRequest request, EventFn callback) override {
            if (state->pending.empty()) throw std::runtime_error("New adapter posted without a matching baseline request");
            Pending old = std::move(state->pending.front());
            state->pending.pop_front();
            std::ofstream(std::string(std::getenv("BODY_CAPTURE"))+"-baseline.jsonl",std::ios::app) << old.request.body << '\n';
            std::ofstream(std::string(std::getenv("BODY_CAPTURE"))+"-current.jsonl",std::ios::app) << request.body << '\n';
            if (request.body != old.request.body || request.url != old.request.url ||
                request.header("Authorization") != old.request.authorization ||
                request.header("Idempotency-Key") != old.request.idempotency_key)
                throw std::runtime_error("Adapter request differs from the baseline bytes");
            return transport->post(std::move(request), [baseline=std::move(old.callback), callback=std::move(callback)](AgentHttpEvent e) {
                baseline({static_cast<LegacyAgentHttpEvent::Kind>(e.kind), e.data, e.error, e.status});
                callback(std::move(e));
            });
        }
        void cancel() override { transport->cancel(); }
    };
    std::shared_ptr<State> state = std::make_shared<State>();
    LegacyOpenAIResponsesAgent baseline;
    OpenAIResponsesAgent current;
public:
    ComparingResponsesAgent(OpenAIResponsesConfig config, std::unique_ptr<IAgentHttpTransport> transport)
        : baseline({config.api_key, config.model, config.endpoint}, std::make_unique<BaselineTransport>(state)),
          current(std::move(config), std::make_unique<ComparingTransport>(state, std::move(transport))) {}
    bool ready() const override { return current.ready(); }
    bool busy() const override { return current.busy(); }
    bool start(const AgentRequest& r) override { baseline.start(r); return current.start(r); }
    bool continue_after_tool(const AgentToolResult& r) override { baseline.continue_after_tool(r); return current.continue_after_tool(r); }
    void cancel() override { baseline.cancel(); current.cancel(); state->pending.clear(); }
    std::optional<AgentEvent> poll() override { baseline.poll(); return current.poll(); }
};
}
